import{_ as d,o as r,c as e,ag as a}from"./chunks/framework.CtWPcAmt.js";const b=JSON.parse('{"title":"WorkBuddy 体验","description":"AI Agent 零基础教程","frontmatter":{"title":"WorkBuddy 体验","description":"AI Agent 零基础教程","layout":"doc","lastUpdated":true},"headers":[],"relativePath":"guide/05-workbuddy.md","filePath":"guide/05-workbuddy.md","lastUpdated":null}'),i={name:"guide/05-workbuddy.md"};function l(o,t,h,n,s,u){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="workbuddy-体验" tabindex="-1">WorkBuddy 体验 <a class="header-anchor" href="#workbuddy-体验" aria-label="Permalink to &quot;WorkBuddy 体验&quot;">​</a></h1><blockquote><p>状态：正文完成；共同基准任务已实测（2026-08-12）</p><p>本机版本：5.3.11（运行记录）；界面截图显示 v5.3.12（以最新界面为准）</p><p>最后本机核对：2026-08-12；订阅核验：2026-08-11</p></blockquote><h2 id="_1-一句话结论" tabindex="-1">1. 一句话结论 <a class="header-anchor" href="#_1-一句话结论" aria-label="Permalink to &quot;1. 一句话结论&quot;">​</a></h2><p><strong>零基础/中文办公最省心的选择之一</strong>：0 人工介入、无需配置模型，成品在客户端内直接 Markdown 渲染，变更统计与逐文件 diff 一目了然（本轮 +647/-0）。实测 5 分 45 秒完成 6/6 交付、消耗 67.25 Credits（本轮托管路径中最高）。注意一处展示不一致：产物列表 6 份但变更列表只显示 5 份，核对时两处都要看。</p><h2 id="_2-测试版本和地区" tabindex="-1">2. 测试版本和地区 <a class="header-anchor" href="#_2-测试版本和地区" aria-label="Permalink to &quot;2. 测试版本和地区&quot;">​</a></h2><ul><li>测试日期：2026-08-12（统一基准实测）；界面截图核验 2026-08-13</li><li>正式产品名称与测试入口：Tencent WorkBuddy（腾讯 AI 智能体桌面工作台，<code>workbuddy.ai</code>）</li><li>地区版本：个人版为美元计价国际站；腾讯云中国区另有产品页（两处价格与活动分开核对）</li><li>具体产品线：Desktop 工作台（助理、项目、专家·技能·连接器、自动化、资料库）</li><li>账号区域与计费币种：个人版美元计费；腾讯云中国区人民币（本页以国际个人版为主，注明两处差异）</li><li>当前账号状态：正常（测试时）</li><li>官方服务是否覆盖当前地区：以官方地区说明为准</li><li>注册、登录与支付前提：账号注册 + 支付方式（国际个人版绑定卡可开启试用）</li><li>账号受限后的申诉与恢复入口：官方支持渠道（未触发）</li><li>桌面客户端版本：5.3.11（运行记录）；截图界面右上角显示 v5.3.12</li><li>操作系统：Windows（本机安装于 <code>E:\\Program\\WorkBuddy</code>）</li><li>官方下载来源：官方桌面安装入口</li><li>入门分组：国内综合型 Agent（腾讯出品，中国区可用）</li><li>主要任务方向：工作 / 自动化 / 资料整理 / 跨场景任务</li><li>开放与后台运行方式：云端（Credits 计费）</li><li>自主程度：中</li><li>建议基础：零基础</li><li>使用方案：Free / Pro</li><li>官方订阅名称、价格与周期：WorkBuddy.ai 个人版 Free $0；Pro $10/月或 $96/年</li><li>套餐内用量单位：Credits（Pro 基础 1,000 + 加赠 1,000 = 2,000 Credits/月；Free 100 Credits/月）</li><li>用量重置时间与结转规则：按月；详见官方订阅页</li><li>官方 API 是否另行计费：模型接入支持提供商、腾讯云 Token Plan、Coding Plan、自定义 API 与 Ollama；自定义模型由供应商结算</li><li>是否支持 BYOK：支持（自定义 API / Ollama 等），模型接入自由度较高</li><li>免费额度及核验来源：Free 100 Credits/月；新用户注册赠送 250 Credits（14 天有效）</li><li>新用户或学生福利：满足条件者绑卡开启 7 天 Pro 试用并得 500 Credits（7 天有效）；限时每日活跃奖励 Free 30 Credits/天、Pro 50 Credits/天（结束时间另行通知，非永久权益）；腾讯云中国区另有「限时双倍 Credits」活动（地区/入口/规则分别核对）</li><li>最后核验日期：2026-08-11</li><li>测试者背景：作者</li></ul><h2 id="_3-下载、安装与首次启动" tabindex="-1">3. 下载、安装与首次启动 <a class="header-anchor" href="#_3-下载、安装与首次启动" aria-label="Permalink to &quot;3. 下载、安装与首次启动&quot;">​</a></h2><ul><li>下载和安装：官方桌面客户端，安装顺利；</li><li>是否必须注册、登录或绑定其他服务：需要账号登录；</li><li>首次权限提示：本轮未出现权限确认弹窗；</li><li>主界面导航：左侧导航（新建任务、助理、项目、专家·技能·连接器、自动化、资料库、更多），中间分日常办公/代码开发/设计创意三类场景入口，右侧概览/产物/引用来源；底部输入框支持 <code>@</code> 引用文件或对话、<code>/</code> 调用技能与指令，并可选择工作空间与权限；</li><li>新手从启动到完成第一个任务：进入「日常办公」→ 选择工作空间 → 粘贴提示词 → 发送；</li><li>是否有只能通过 CLI/TUI 才能完成的重要能力：未发现。</li></ul><h2 id="_4-免费额度、订阅与计费" tabindex="-1">4. 免费额度、订阅与计费 <a class="header-anchor" href="#_4-免费额度、订阅与计费" aria-label="Permalink to &quot;4. 免费额度、订阅与计费&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>实际记录</th><th>官方来源</th><th>最后核验日期</th></tr></thead><tbody><tr><td>免费额度</td><td>Free 100 Credits/月；新用户 250 Credits（14 天）；每日活跃 30 Credits/天（限时）</td><td>WorkBuddy 定价/积分说明</td><td>2026-08-11</td></tr><tr><td>官方订阅</td><td>Pro $10/月或 $96/年，2,000 Credits/月</td><td>WorkBuddy 订阅政策</td><td>2026-08-11</td></tr><tr><td>用量单位与重置规则</td><td>Credits，按月重置</td><td>官方积分说明</td><td>2026-08-11</td></tr><tr><td>新用户或学生福利</td><td>绑卡 7 天 Pro 试用 + 500 Credits；腾讯云中国区双倍 Credits（分别核验）</td><td>官方文档</td><td>2026-08-11</td></tr><tr><td>API 或 BYOK</td><td>支持自定义 API / Ollama / 各家 Coding Plan</td><td>模型配置文档</td><td>2026-08-11</td></tr></tbody></table><p><strong>实测补充</strong>：本轮 Auto 配置，界面显示模型 <code>GLM-5.2</code>；实际消耗 67.25 Credits（测试者确认）。账号界面曾显示「今日可领 100 积分」，属于带日期和账号条件的客户端可见活动，不写成长期固定福利。</p><h2 id="_5-核心能力" tabindex="-1">5. 核心能力 <a class="header-anchor" href="#_5-核心能力" aria-label="Permalink to &quot;5. 核心能力&quot;">​</a></h2><ul><li>能处理哪些材料：文档、办公材料、多格式文件；统一基准任务中一次生成 6 份 Markdown 成品；</li><li>能调用哪些工具：文件系统、任务对话、产物导航、引用来源、变更 diff（本轮用到）；自动化、资料库等入口可见未在本轮触发；</li><li>代表性功能：任务总结报告、产物文件卡片、Markdown 直接渲染、文件变更列表 + 逐文件 diff、<code>@</code>/<code>/</code> 指令；</li><li>哪些能力实际验证过：共同基准任务完整链路；哪些只来自官方说明：自动化任务、视频生成等扩展入口。</li></ul><h2 id="_6-界面与工作方式" tabindex="-1">6. 界面与工作方式 <a class="header-anchor" href="#_6-界面与工作方式" aria-label="Permalink to &quot;6. 界面与工作方式&quot;">​</a></h2><ul><li>运行位置：官方桌面应用（云端处理）；</li><li>用户如何观察和控制执行过程：中间工作区看任务总结与产物卡片，右侧「概览 / 产物 / 引用来源」查看详情，变更面板看行级 diff。</li></ul><table tabindex="0"><thead><tr><th>维度</th><th>观察记录</th><th>适用前提</th></tr></thead><tbody><tr><td>新手上手难度</td><td>低；导航与场景入口分层清楚</td><td>—</td></tr><tr><td>账号与地区可用性</td><td>正常；注意国际个人版与腾讯云中国区两套价格</td><td>—</td></tr><tr><td>图形界面清晰度</td><td>三栏布局，导航、任务、信息栏分明</td><td>—</td></tr><tr><td>任务状态反馈</td><td>任务总结报告 + 产物卡片 + 完成提示</td><td>—</td></tr><tr><td>权限提示与确认</td><td>本轮 0 次</td><td>—</td></tr><tr><td>上下文处理</td><td>只读取 input 材料包，未发现越界读取</td><td>—</td></tr><tr><td>过程可控性</td><td>0 人工介入；产物位置明确</td><td>—</td></tr><tr><td>结果定位与验证</td><td>产物列表 + Markdown 渲染 + 变更 diff；<strong>注意：产物 6 份 vs 变更列表 5 份不一致</strong></td><td>需两处核对</td></tr><tr><td>生态与扩展</td><td>专家/技能/连接器、自动化、资料库入口</td><td>未逐一实测</td></tr></tbody></table><p>界面细节见 「界面讲解文档」(docs/11-interface-guides/01-workbuddy.md)（三张截图：整体界面、概览与产物、变更与 diff）。</p><h2 id="_7-三类实测任务" tabindex="-1">7. 三类实测任务 <a class="header-anchor" href="#_7-三类实测任务" aria-label="Permalink to &quot;7. 三类实测任务&quot;">​</a></h2><h3 id="_7-1-共同基准任务-2026-08-12" tabindex="-1">7.1 共同基准任务（2026-08-12） <a class="header-anchor" href="#_7-1-共同基准任务-2026-08-12" aria-label="Permalink to &quot;7.1 共同基准任务（2026-08-12）&quot;">​</a></h3><h4 id="任务背景" tabindex="-1">任务背景 <a class="header-anchor" href="#任务背景" aria-label="Permalink to &quot;任务背景&quot;">​</a></h4><p>使用冻结的教程材料包（<code>input/</code> 7 份文件），整理 AI Agent 教程材料，生成六个指定交付文件并自检。</p><h4 id="完整输入" tabindex="-1">完整输入 <a class="header-anchor" href="#完整输入" aria-label="Permalink to &quot;完整输入&quot;">​</a></h4><p>冻结材料包 + <code>workbuddy-prompt.md</code> 统一提示。</p><h4 id="执行过程" tabindex="-1">执行过程 <a class="header-anchor" href="#执行过程" aria-label="Permalink to &quot;执行过程&quot;">​</a></h4><p>打开 WorkBuddy → 进入「日常办公」→ 选择运行目录 → 保持 Auto 与默认权限 → 粘贴统一提示发送。</p><h4 id="最终结果" tabindex="-1">最终结果 <a class="header-anchor" href="#最终结果" aria-label="Permalink to &quot;最终结果&quot;">​</a></h4><p>六份指定文件按顺序生成（07:23:45 首文件至 07:26:43 末文件），总用时 5 分 45 秒（测试者记录；首末文件间隔 2 分 58 秒）。</p><h4 id="验收情况" tabindex="-1">验收情况 <a class="header-anchor" href="#验收情况" aria-label="Permalink to &quot;验收情况&quot;">​</a></h4><ul><li>交付：6/6 一次通过，无报错/中断/重试；7/7 输入 SHA-256 与基线一致；</li><li>内容亮点：结构化整理、信息缺口识别、新手化目录组织较好；没有编造 Claude 封号原因；</li><li>内容偏差：自行生成 21 章目录，把输入包未提供的正式目录/任务/模板当作项目待办——只能作为基准答卷与内容建议，不能覆盖正式 23 章框架；</li><li>变更展示：<code>+647/-0</code>、逐文件 diff 清楚；但「查看所有变更」只显示 5 份，漏 <code>06-self-check.md</code>，与 6 份产物列表不一致；</li><li>指标：澄清 0 / 权限确认 0 / 人工指导 0 / 恢复 0。</li></ul><table tabindex="0"><thead><tr><th>指标</th><th>记录</th></tr></thead><tbody><tr><td>开始与完成时间</td><td>2026-08-12 07:23:45 — 07:26:43</td></tr><tr><td>总用时</td><td>5 分 45 秒</td></tr><tr><td>人工介入次数及原因</td><td>0</td></tr><tr><td>权限确认次数</td><td>0</td></tr><tr><td>生成或修改的交付文件</td><td>6/6 指定文件</td></tr><tr><td>是否一次通过验收</td><td>是</td></tr><tr><td>失败后的恢复路径</td><td>未触发</td></tr></tbody></table><h3 id="_7-2-优势任务" tabindex="-1">7.2 优势任务 <a class="header-anchor" href="#_7-2-优势任务" aria-label="Permalink to &quot;7.2 优势任务&quot;">​</a></h3><p>候选：自动化任务、资料整理与跨场景任务（产品定位方向）。<strong>待 benchmark v2 统一测试</strong>。</p><h3 id="_7-3-边界任务" tabindex="-1">7.3 边界任务 <a class="header-anchor" href="#_7-3-边界任务" aria-label="Permalink to &quot;7.3 边界任务&quot;">​</a></h3><p>候选：Credits 耗尽、自动任务出错或权限受限时的恢复。<strong>本轮未触发</strong>；「材料缺失 ≠ 项目未完成」偏差已由验收流程标注。</p><h2 id="_8-遇到的问题与恢复" tabindex="-1">8. 遇到的问题与恢复 <a class="header-anchor" href="#_8-遇到的问题与恢复" aria-label="Permalink to &quot;8. 遇到的问题与恢复&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>出现条件</th><th>对结果的影响</th><th>恢复步骤</th><th>新手能否独立处理</th></tr></thead><tbody><tr><td>运行上下文与输入材料范围不一致</td><td>Agent 只读取刻意裁剪的 input/</td><td>把仓库已有内容列为缺失，生成 21 章目录</td><td>不覆盖正式框架；验收标注材料边界</td><td>需要教程解释「材料缺失」≠「项目未完成」</td></tr><tr><td>产物列表与变更列表数量不一致</td><td>变更视图漏列 06-self-check.md</td><td>交付清单与变更视图两套口径</td><td>两处都查看，以产物列表 + 文件系统为准</td><td>新手可能只信其中一个视图</td></tr></tbody></table><p>本轮未出现执行错误或中断。Credits 消耗相对同轮产品偏高（67.25），教程需提示用量观察。</p><h2 id="_9-适合与不适合" tabindex="-1">9. 适合与不适合 <a class="header-anchor" href="#_9-适合与不适合" aria-label="Permalink to &quot;9. 适合与不适合&quot;">​</a></h2><h3 id="更适合" tabindex="-1">更适合 <a class="header-anchor" href="#更适合" aria-label="Permalink to &quot;更适合&quot;">​</a></h3><ul><li>零基础、中文办公为主的新手（0 介入、无需配置模型）；</li><li>希望「成品看得见、改了什么看得见」的用户（Markdown 渲染 + 行级 diff）；</li><li>需要自动化、资料库等扩展能力的办公场景。</li></ul><h3 id="可能不适合" tabindex="-1">可能不适合 <a class="header-anchor" href="#可能不适合" aria-label="Permalink to &quot;可能不适合&quot;">​</a></h3><ul><li>对 Credits 消耗敏感的用户（本轮 67.25 Credits 为托管路径最高，需按自身任务量评估）；</li><li>需要强代码/Git 工作流的用户（代码能力本轮未验证，建议对照 Qoder/ZCode/Codex）；</li><li>追求「交付清单与变更视图完全一致」的严格核对者（存在 6 vs 5 不一致，需人工注意）。</li></ul><h2 id="_10-最终结论" tabindex="-1">10. 最终结论 <a class="header-anchor" href="#_10-最终结论" aria-label="Permalink to &quot;10. 最终结论&quot;">​</a></h2><ul><li>是否推荐新手试用：<strong>推荐</strong>，作为国内综合型首选试用之一；</li><li>什么条件下值得购买官方订阅：Free 额度（100 Credits + 新用户 250 + 每日活跃）用完后、日常任务量稳定时考虑 Pro；建议先观察自己单任务的 Credits 消耗再决定；</li><li>最适合作为主 Agent、辅助 Agent 还是专用工具：<strong>国内办公场景主 Agent 候选</strong>；自动化与资料库适合作为长期辅助；</li><li>与相邻产品的差异：与 TraeWork 同为国内综合型 0 介入，但 WorkBuddy 的变更可见性（+647/-0 diff）有截图实证，TraeWork 变更环节未验证；成本口径不同（Credits vs 积分）不可横比；</li><li>仍需要后续版本继续核验：变更列表遗漏问题的产品修复、自动化/资料库实测、版本 5.3.11→5.3.12 差异、中国区人民币购买路径。</li></ul><h2 id="附录-a-截图清单" tabindex="-1">附录 A：截图清单 <a class="header-anchor" href="#附录-a-截图清单" aria-label="Permalink to &quot;附录 A：截图清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>截图</th><th>用途</th><th>日期或版本</th><th>是否脱敏</th><th>替代文字</th></tr></thead><tbody><tr><td>整体界面.png</td><td>三栏工作台、导航与任务总结</td><td>v5.3.12</td><td>是</td><td>三栏式综合工作台</td></tr><tr><td>概览详情.png</td><td>任务进程与产物渲染</td><td>同上</td><td>是</td><td>概览与产物预览</td></tr><tr><td>变更详情.png</td><td>+647/-0 与逐文件 diff</td><td>同上</td><td>是</td><td>变更面板与 diff</td></tr></tbody></table><h2 id="附录-b-信息来源" tabindex="-1">附录 B：信息来源 <a class="header-anchor" href="#附录-b-信息来源" aria-label="Permalink to &quot;附录 B：信息来源&quot;">​</a></h2><ul><li><a href="https://www.workbuddy.ai/docs/zh/workbuddy/Overview" target="_blank" rel="noreferrer">Tencent WorkBuddy 简介</a>、<a href="https://www.workbuddy.ai/docs/zh/workbuddy/Subscription" target="_blank" rel="noreferrer">订阅政策</a>、<a href="https://www.workbuddy.ai/docs/zh/workbuddy/pricing" target="_blank" rel="noreferrer">定价</a>、<a href="https://www.workbuddy.ai/docs/zh/workbuddy/credits" target="_blank" rel="noreferrer">积分说明</a>、<a href="https://www.workbuddy.ai/docs/zh/workbuddy/From-Beginner-to-Expert-Guide/Function-Description/Model" target="_blank" rel="noreferrer">模型配置</a>（访问日期 2026-08-11）</li><li><a href="https://cloud.tencent.com/product/workbuddy" target="_blank" rel="noreferrer">腾讯云 WorkBuddy 产品页</a>（访问日期 2026-08-11，注意与国际个人版分开）</li><li>运行记录：<code>research/runs/2026-08-12-workbuddy-v5.3.11/run-record.md</code></li><li>界面讲解：<code>docs/11-interface-guides/01-workbuddy.md</code></li></ul><h2 id="附录-c-内容性质标记" tabindex="-1">附录 C：内容性质标记 <a class="header-anchor" href="#附录-c-内容性质标记" aria-label="Permalink to &quot;附录 C：内容性质标记&quot;">​</a></h2><p>本文区分：官方事实（价格、额度、模型接入）、实际测试（共同基准任务全程）、作者观察（界面体验）、待验证（自动化能力、中国区购买路径、版本差异）。5 分 45 秒与 67.25 Credits 只对应 Auto/GLM-5.2、本账号、本版本与默认权限，不推广到其他配置。</p>',50)])])}const k=d(i,[["render",l]]);export{b as __pageData,k as default};
